  "request": "Hey, can we add a specific env var to control output capture? I'd like LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED to override the default and let me turn off output recording without touching the code.",
  "edits": [
    {
      "path": "langfuse/_client/observe.py",
      "search": "function_io_capture_enabled = os.environ.get(
    LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED, "True"
).lower() not in ("false", "0")",
      "replace": "function_io_capture_enabled = os.environ.get(
    LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED, "True"
).lower() not in ("false", "0")

        # New env var to control only output capture. If set, it overrides the generic IO setting.
        output_capture_env = os.environ.get(
            "LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED", None
        )
        if output_capture_env is not None:
            output_capture_enabled = output_capture_env.lower() not in ("false", "0")
        else:
            output_capture_enabled = function_io_capture_enabled"
    },
    {
      "path": "langfuse/_client/observe.py",
