  "test_path": "tests/unit/test_observe_output_env.py",
  "test": "import pytest
from langfuse import observe
from langfuse._client.observe import _ContextPreservedSyncGeneratorWrapper
from langfuse._client.attributes import LangfuseOtelSpanAttributes


def _finished_spans_by_name(memory_exporter, name):
    return [span for span in memory_exporter.get_finished_spans() if span.name == name]


def test_output_capture_env_var_disables_output_capture(monkeypatch, langfuse_memory_client, memory_exporter):
    # Set env var to explicitly disable output capture
    monkeypatch.setenv("LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED", "false")

    @observe(name="env_test")
    def foo() -> str:
        return "hi"

    result = foo()
    assert result == "hi"

    # Flush to ensure spans are exported
    langfuse_memory_client.flush()

    spans = _finished_spans_by_name(memory_exporter, "env_test")
    assert len(spans) == 1
    span = spans[0]
    # Output should not be recorded when disabled via env var
    assert LangfuseOtelSpanAttributes.OBSERVATION_OUTPUT not in span.attributes"
}
